export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "手紙が届いたのは、火曜日の朝だった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王城に郵便配達は来ない。三百年のあいだ、この城に届けられたものは三種類しかなかった。果たし状と、呪いと、勇者本人だ。だから秘書が淡いクリーム色の封筒を玉座の肘掛けに置いたとき、魔王はずいぶん長いことそれを見つめていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "封筒の宛名は、とても几帳面な字で書かれていた。封をしていたのは血ではなく、ご飯粒だった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）嫌な予感がする。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "勇者からです。読み上げましょうか。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "読め。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「拝啓　魔王陛下。このたび一身上の都合により、本月末日をもちまして勇者の職を辞することといたしました。」", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「十二年間、大変お世話になりました。攻め込むたびに、貴城の細やかなお心配りを感じておりました。罠の手入れは常に行き届き、口上も一度として同じものはございませんでした。」", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）口上は毎年、書き直しているからな。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「ですが私も今年で三十四になり、膝の具合が思わしくありません。前回、第七層の回転刃の罠を転がり抜けた折には、ひと月寝込みました。人生には、ほかにもやれることがあるのではないかと思うようになりました。」", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「東の山のふもとに土地を買い、かぶを育てるつもりです。土はよく、ご近所の方々も親切です。末筆ながら、貴城の魔業のますますのご発展をお祈り申し上げます。敬具　勇者」", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "裏にもう一行ございます。「追伸　かぶが採れましたら、ひと箱お送りします。」", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "玉座の間が静まりかえった。高窓から夕陽が斜めに差しこみ、石柱の影を長く引きのばしている。一本、また一本と床に横たわるそれは、誰も座ろうとしないベンチの列のようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）かぶ。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は手紙を受け取り、もう一度読んだ。字に震えはなく、書き損じもない。下書きをしてから清書したのが見てとれた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "礼儀正しい手紙だった。そこがいちばん、たちが悪い。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "呪われた勇者は戻ってくる。倒された勇者も戻ってくる。恨みを抱いた勇者なら、必ず戻ってくる。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "礼儀正しい勇者は、戻ってこない。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "セリン、今日は何日だ。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Weary },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "十四日です。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "月末を過ぎれば、もう誰も余を倒しには来ないということか。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "文面を拝見する限り、そのとおりかと。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は玉座に背をあずけた。玉座は硬い。三百年前に彼が自ら選んだもので、決め手は「座ると威厳が出るから」だった。いつかこの上で、何をすればいいのかわからないまま座りつづける日が来るなど、考えたこともなかった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼のカレンダーには、毎月第一土曜日に赤い丸がついている。その前の晩には罠を点検し、誰もいない大広間に向かって口上を一度通しで練習し、マントをクリーニングに出す。あの赤い丸が、ひと月をまるごと支えていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）この先は、白紙があるだけだ。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "勇者のいない魔王など、ただ大きな家に住んでいるだけの者にすぎん。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "たしかに、大きなお住まいです。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "そういう話ではない。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "存じております。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "セリンが彼に仕えて百十年になる。そのあいだ、一度も取り乱したことがない。東翼が火事になったときも、地下牢のスライムが一斉にストライキを起こしたときも、勇者がはじめて攻め込んできて魔王が口上を忘れたときも。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は手にしたファイルを開き、紙を一枚抜き出した。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "では、補充いたしましょう。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "何をだ。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "勇者です。欠員が出たら、募集をかける。それだけのことです。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "宿敵は欠員ではない。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "本日午前九時付で、欠員となりました。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は紙をくるりと回して、魔王のほうへ向けた。求人票だった。城の公印まで、すでに押してある。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「魔王城　宿敵募集（一名）。応募資格：正義感のある方。定期的に来訪できる方。ストレス耐性のある方。未経験可。給与：応相談。討伐可。」", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "「討伐可」というのは、余のことか。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "はい。はっきり書いておいたほうが、誠意が伝わるかと。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "いつ貼った。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "陛下が手紙を三度目に読み返していらしたときです。ふもとの村の掲示板と、市場の入口の告知板に。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）手紙を読み上げる前に、もう書いてあったのだな。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は尋ねなかった。百十年も一緒にいれば、聞かずにおいたほうがいいこともある。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "誰か来るのか。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "すでに三名の応募がございました。面接は明日の午前に入れてあります。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は求人票を見つめた。紙は真新しく、墨は黒々としていて、「討伐可」の三文字だけがひときわ端正に書かれていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……玉座の間は、どう設営する。", background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お任せください。", background: Background.Root_Act1_S0, portrait: Portrait.Serin_Smile },
];
